import{b as a,O as i,g as t,j as e}from"./chunks/framework.DcaUmd3X.js";const n="/assets/image-7.DcmXogQI.webp",h="data:image/webp;base64,",l="/assets/image.DnHruWKF.webp",u=JSON.parse('{"title":"分支概念与操作","description":"","frontmatter":{},"headers":[],"relativePath":"git/branch/branch-basics/index.md","filePath":"Git操作手册/3.分支管理/01.分支概念与操作.md","lastUpdated":1783947942000}'),p={name:"git/branch/branch-basics/index.md"};function o(d,s,r,c,k,g){return i(),t("div",null,[...s[0]||(s[0]=[e('<h1 id="分支概念与操作" tabindex="-1">分支概念与操作 <a class="header-anchor" href="#分支概念与操作" aria-label="Permalink to &quot;分支概念与操作&quot;">​</a></h1><blockquote><p>git branch / git switch / git merge，并行开发的基础</p></blockquote><h2 id="什么是分支" tabindex="-1">什么是分支 <a class="header-anchor" href="#什么是分支" aria-label="Permalink to &quot;什么是分支&quot;">​</a></h2><p>想象你在写一个新功能，写到一半，产品经理说&quot;线上有个紧急 bug 要立刻修&quot;。你的新功能还没写完，不能跟着 bug 修复一起上线——这时候你就需要两条线并行工作：</p><p><img src="'+n+`" alt="alt text"></p><ul><li><strong>master</strong>：线上代码，A → B 一路往前走</li><li><strong>feature</strong>：从 B 拉出来做新功能，，写到一半暂停</li><li><strong>hotfix</strong>：从 master 拉出来紧急修 bug，修完合回 master（C），最后 feature 继续开发完成，也合回 master（D）</li></ul><p><strong>分支就是一条独立的开发线。</strong> 在 Git 里，分支只是一个指向某次提交的&quot;指针&quot;，创建和切换几乎瞬间完成——这是 Git 和其他版本控制系统最大的区别之一。</p><h2 id="查看分支" tabindex="-1">查看分支 <a class="header-anchor" href="#查看分支" aria-label="Permalink to &quot;查看分支&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># * master    ← * 表示当前所在的分支</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   feature-a</span></span></code></pre></div><h2 id="创建分支" tabindex="-1">创建分支 <a class="header-anchor" href="#创建分支" aria-label="Permalink to &quot;创建分支&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span></span></code></pre></div><p>这条命令<strong>只是创建</strong>了一个名叫 <code>feature-login</code> 的分支，但你还在 <code>master</code> 上。要切换到新分支，需要再敲一条命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span></span></code></pre></div><p>创建 + 切换一步到位：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 新版写法，推荐</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 旧版写法，也能用</span></span></code></pre></div><blockquote><p>💡 Git 2.23 之后推荐用 <code>switch</code>（切换分支）和 <code>restore</code>（还原文件），把 <code>checkout</code> 的两种职责拆开了。遇到 <code>git checkout -b</code> 知道是什么意思就行。</p></blockquote><h2 id="在分支上做开发" tabindex="-1">在分支上做开发 <a class="header-anchor" href="#在分支上做开发" aria-label="Permalink to &quot;在分支上做开发&quot;">​</a></h2><p>切换到 <code>feature-login</code> 后，正常修改文件、提交：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 改代码...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;完成登录页面布局&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 继续改...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> commit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;接入登录接口&quot;</span></span></code></pre></div><p>这些提交都发生在 <code>feature-login</code> 分支上，<code>master</code> 分支完全不受影响。你可以随时切回 <code>master</code>——那里还是原来的样子。</p><h2 id="合并分支" tabindex="-1">合并分支 <a class="header-anchor" href="#合并分支" aria-label="Permalink to &quot;合并分支&quot;">​</a></h2><p>功能开发完成，把 <code>feature-login</code> 的代码合并回 <code>master</code>：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> master</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">             # 先切到要&quot;接收&quot;的分支</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 把 feature-login 合并进来</span></span></code></pre></div><p>合并有两种情况：</p><h3 id="快进合并-fast-forward" tabindex="-1">快进合并（Fast-forward） <a class="header-anchor" href="#快进合并-fast-forward" aria-label="Permalink to &quot;快进合并（Fast-forward）&quot;">​</a></h3><p>如果 <code>master</code> 在 <code>feature-login</code> 创建之后没有新提交，Git 直接把 <code>master</code> 指针挪到 <code>feature-login</code> 的位置——像快进一样，不会产生新节点：</p><p><img src="`+h+'" alt="alt text"></p><h3 id="三路合并-3-way-merge" tabindex="-1">三路合并（3-way merge） <a class="header-anchor" href="#三路合并-3-way-merge" aria-label="Permalink to &quot;三路合并（3-way merge）&quot;">​</a></h3><p>如果两个分支都有新提交，Git 会把两边的改动合并到一起，生成一个新的&quot;合并提交&quot;：</p><p><img src="'+l+`" alt="alt text"></p><h2 id="删除分支" tabindex="-1">删除分支 <a class="header-anchor" href="#删除分支" aria-label="Permalink to &quot;删除分支&quot;">​</a></h2><p>合并完成后，<code>feature-login</code> 的历史已经并入 <code>master</code>，可以删掉了：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 安全删除：已合并的才能删</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> feature-login</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 强制删除：没合并也删（谨慎）</span></span></code></pre></div><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>分支操作就四件事：</p><ol><li><strong>创建</strong> — <code>git switch -c 分支名</code></li><li><strong>切换</strong> — <code>git switch 分支名</code></li><li><strong>合并</strong> — <code>git merge 分支名</code></li><li><strong>删除</strong> — <code>git branch -d 分支名</code></li></ol><p>每天在用的流程：<strong>开分支 → 在上面改代码提交 → 合并回 master → 删分支</strong>。后面几章会展开讲冲突解决、分支策略和 rebase，让这套流程更稳。</p><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>创建 <code>feature-test</code> 分支，切换过去，做一次提交，再切回 <code>master</code>，确认 <code>master</code> 上没有那个提交</li><li>把 <code>feature-test</code> 合并到 <code>master</code>，观察是快进合并还是三路合并</li><li>合并后用 <code>git branch -d</code> 删除 <code>feature-test</code></li><li>创建两个分支分别做一次提交，再合并，模拟三路合并的场景</li></ol>`,39)])])}const b=a(p,[["render",o]]);export{u as __pageData,b as default};
